package com.example.bookstore.model;

import jakarta.persistence.Entity; // JPA annotation for entities
import jakarta.persistence.GeneratedValue; // Strategy for primary key generation
import jakarta.persistence.GenerationType; // Types of primary key generation strategies
import jakarta.persistence.Id; // Marks a field as the primary key
import jakarta.validation.constraints.DecimalMin; // Validation: numeric value must be greater than or equal to a minimum
import jakarta.validation.constraints.NotBlank; // Validation: string must not be null and must contain at least one non-whitespace character
import jakarta.validation.constraints.NotNull; // Validation: field must not be null

import java.math.BigDecimal; // Used for precise monetary calculations

/**
 * Represents a Book entity in the bookstore.
 * This class is mapped to a database table using JPA annotations.
 */
@Entity // Declares this class as a JPA entity, meaning it corresponds to a table in the database
public class Book {

    @Id // Marks the 'id' field as the primary key for the entity
    @GeneratedValue(strategy = GenerationType.IDENTITY) // Configures the primary key to be auto-generated by the database
    private Long id; // Unique identifier for the book

    @NotBlank(message = "Title cannot be empty") // Validation: Title must not be null and not just whitespace
    private String title; // The title of the book

    @NotBlank(message = "Author cannot be empty") // Validation: Author must not be null and not just whitespace
    private String author; // The author of the book

    @NotBlank(message = "ISBN cannot be empty") // Validation: ISBN must not be null and not just whitespace
    private String isbn; // International Standard Book Number (unique identifier for books)

    @NotNull(message = "Price cannot be null") // Validation: Price must not be null
    @DecimalMin(value = "0.01", message = "Price must be positive") // Validation: Price must be at least 0.01
    private BigDecimal price; // The price of the book, using BigDecimal for precision

    // Default constructor (required by JPA)
    public Book() {
    }

    // Constructor to easily create a new Book object (without ID, as it's auto-generated)
    public Book(String title, String author, String isbn, BigDecimal price) {
        this.title = title;
        this.author = author;
        this.isbn = isbn;
        this.price = price;
    }

    // --- Getters and Setters ---
    // These methods provide access to the private fields of the Book class.

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public String getTitle() {
        return title;
    }

    public void setTitle(String title) {
        this.title = title;
    }

    public String getAuthor() {
        return author;
    }

    public void setAuthor(String author) {
        this.author = author;
    }

    public String getIsbn() {
        return isbn;
    }

    public void setIsbn(String isbn) {
        this.isbn = isbn;
    }

    public BigDecimal getPrice() {
        return price;
    }

    public void setPrice(BigDecimal price) {
        this.price = price;
    }

    // You might also want to override toString(), equals(), and hashCode() for better object handling.
    // For brevity in this beginner example, they are omitted.
}
