package com.example.bookstore.service;

import com.example.bookstore.exception.BookNotFoundException;
import com.example.bookstore.model.Book;
import com.example.bookstore.repository.BookRepository;
import org.springframework.beans.factory.annotation.Autowired; // For automatic dependency injection
import org.springframework.stereotype.Service; // Marks this class as a Spring Service component

import java.util.List; // For returning collections of books

/**
 * Service layer class for managing Book entities.
 * This class encapsulates the business logic related to books.
 * It interacts with the BookRepository to perform CRUD operations on the database.
 */
@Service // Indicates that this class is a service component in the Spring application context
public class BookService {

    private final BookRepository bookRepository; // Dependency on the BookRepository

    /**
     * Constructor for BookService.
     * Spring automatically injects an instance of BookRepository because of @Autowired.
     * This is an example of constructor injection, which is recommended for mandatory dependencies.
     *
     * @param bookRepository The repository used to access book data.
     */
    @Autowired
    public BookService(BookRepository bookRepository) {
        this.bookRepository = bookRepository;
    }

    /**
     * Retrieves all books from the database.
     *
     * @return A list of all {@link Book} objects.
     */
    public List<Book> getAllBooks() {
        return bookRepository.findAll(); // Uses Spring Data JPA's findAll method
    }

    /**
     * Retrieves a single book by its ID.
     *
     * @param id The ID of the book to retrieve.
     * @return The {@link Book} object if found.
     * @throws BookNotFoundException if a book with the given ID does not exist.
     */
    public Book getBookById(Long id) {
        // Uses Spring Data JPA's findById, which returns an Optional.
        // If the book is not present, it throws our custom BookNotFoundException.
        return bookRepository.findById(id)
                .orElseThrow(() -> new BookNotFoundException(id));
    }

    /**
     * Creates a new book in the database.
     *
     * @param book The {@link Book} object to be saved.
     * @return The saved {@link Book} object, including its newly generated ID.
     */
    public Book createBook(Book book) {
        return bookRepository.save(book); // Uses Spring Data JPA's save method
    }

    /**
     * Updates an existing book in the database.
     *
     * @param id The ID of the book to update.
     * @param bookDetails A {@link Book} object containing the updated details.
     * @return The updated {@link Book} object.
     * @throws BookNotFoundException if a book with the given ID does not exist.
     */
    public Book updateBook(Long id, Book bookDetails) {
        // First, check if the book exists
        Book existingBook = bookRepository.findById(id)
                .orElseThrow(() -> new BookNotFoundException(id));

        // Update the fields of the existing book with the new details
        existingBook.setTitle(bookDetails.getTitle());
        existingBook.setAuthor(bookDetails.getAuthor());
        existingBook.setIsbn(bookDetails.getIsbn());
        existingBook.setPrice(bookDetails.getPrice());

        // Save the updated book back to the database
        return bookRepository.save(existingBook);
    }

    /**
     * Deletes a book from the database by its ID.
     *
     * @param id The ID of the book to delete.
     * @throws BookNotFoundException if a book with the given ID does not exist.
     */
    public void deleteBook(Long id) {
        // Check if the book exists before attempting to delete it
        if (!bookRepository.existsById(id)) {
            throw new BookNotFoundException(id);
        }
        bookRepository.deleteById(id); // Uses Spring Data JPA's deleteById method
    }
}
