import org.springframework.web.bind.annotation.DeleteMapping; // Annotation for mapping HTTP DELETE requests
import org.springframework.web.bind.annotation.GetMapping; // Annotation for mapping HTTP GET requests
import org.springframework.web.bind.annotation.PathVariable; // Annotation for extracting values from URI templates
import org.springframework.web.bind.annotation.PostMapping; // Annotation for mapping HTTP POST requests
import org.springframework.web.bind.annotation.PutMapping; // Annotation for mapping HTTP PUT requests
import org.springframework.web.bind.annotation.RequestBody; // Annotation for binding the HTTP request body to a method parameter
import org.springframework.web.bind.annotation.RequestMapping; // Annotation for mapping web requests onto specific handler classes and/or handler methods
import org.springframework.web.bind.annotation.RestController; // Annotation to define a RESTful web service controller

import java.util.List; // For returning collections of books

/**
 * REST controller for managing Book resources.
 * This class defines the API endpoints for performing CRUD operations on books.
 */
@RestController // Marks this class as a REST controller, automatically serializing return objects to JSON/XML
@RequestMapping("/api/books") // Base path for all endpoints in this controller
public class BookController {

    private final BookService bookService; // Dependency on the BookService

    /**
     * Constructor for BookController.
     * Spring automatically injects an instance of BookService because of @Autowired.
     * This is constructor injection, a best practice for mandatory dependencies.
     *
     * @param bookService The service layer for book operations.
     */
    @Autowired
    public BookController(BookService bookService) {
        this.bookService = bookService;
    }

    /**
     * Handles HTTP GET requests to retrieve all books.
     * Endpoint: GET /api/books
     *
     * @return A {@link ResponseEntity} containing a list of all {@link Book} objects and an HTTP status of OK.
     */
    @GetMapping // Maps HTTP GET requests to /api/books
    public ResponseEntity<List<Book>> getAllBooks() {
        List<Book> books = bookService.getAllBooks();
        return ResponseEntity.ok(books); // Returns 200 OK with the list of books in the response body
    }

    /**
     * Handles HTTP GET requests to retrieve a single book by its ID.
     * Endpoint: GET /api/books/{id}
     *
     * @param id The ID of the book to retrieve, extracted from the URL path.
     * @return A {@link ResponseEntity} containing the {@link Book} object and an HTTP status of OK.
     *         If the book is not found, the {@link GlobalExceptionHandler} will catch {@link com.example.bookstore.exception.BookNotFoundException}
     *         and return an appropriate error response.
     */
    @GetMapping("/{id}") // Maps HTTP GET requests to /api/books/{id}
    public ResponseEntity<Book> getBookById(@PathVariable Long id) {
        Book book = bookService.getBookById(id);
        return ResponseEntity.ok(book); // Returns 200 OK with the found book
    }

    /**
     * Handles HTTP POST requests to create a new book.
     * Endpoint: POST /api/books
     *
     * @param book The {@link Book} object to be created, deserialized from the request body.
     *             The @Valid annotation triggers validation checks defined in the Book model.
     * @return A {@link ResponseEntity} containing the newly created {@link Book} object and an HTTP status of CREATED.
     */
    @PostMapping // Maps HTTP POST requests to /api/books
    public ResponseEntity<Book> createBook(@Valid @RequestBody Book book) {
        Book createdBook = bookService.createBook(book);
        return new ResponseEntity<>(createdBook, HttpStatus.CREATED); // Returns 201 Created with the new book
    }

    /**
     * Handles HTTP PUT requests to update an existing book.
     * Endpoint: PUT /api/books/{id}
     *
     * @param id The ID of the book to update, extracted from the URL path.
     * @param bookDetails A {@link Book} object containing the updated details, deserialized from the request body.
     *                    The @Valid annotation triggers validation checks defined in the Book model.
     * @return A {@link ResponseEntity} containing the updated {@link Book} object and an HTTP status of OK.
     *         If the book is not found, the {@link GlobalExceptionHandler} will catch {@link com.example.bookstore.exception.BookNotFoundException}
     *         and return an appropriate error response.
     */
    @PutMapping("/{id}") // Maps HTTP PUT requests to /api/books/{id}
    public ResponseEntity<Book> updateBook(@PathVariable Long id, @Valid @RequestBody Book bookDetails) {
        Book updatedBook = bookService.updateBook(id, bookDetails);
        return ResponseEntity.ok(updatedBook); // Returns 200 OK with the updated book
    }

    /**
     * Handles HTTP DELETE requests to delete a book by its ID.
     * Endpoint: DELETE /api/books/{id}
     *
     * @param id The ID of the book to delete, extracted from the URL path.
     * @return A {@link ResponseEntity} with no content and an HTTP status of NO_CONTENT.
     *         If the book is not found, the {@link GlobalExceptionHandler} will catch {@link com.example.bookstore.exception.BookNotFoundException}
     *         and return an appropriate error response.
     */
    @DeleteMapping("/{id}") // Maps HTTP DELETE requests to /api/books/{id}
    public ResponseEntity<Void> deleteBook(@PathVariable Long id) {
        bookService.deleteBook(id);
        return ResponseEntity.noContent().build(); // Returns 204 No Content
    }
}
