package com.example.bookstore.exception;

import org.springframework.http.HttpStatus; // HTTP status codes
import org.springframework.http.ResponseEntity; // Represents the whole HTTP response
import org.springframework.web.bind.MethodArgumentNotValidException; // Exception thrown when @Valid fails
import org.springframework.web.bind.annotation.ControllerAdvice; // Annotation for global exception handling
import org.springframework.web.bind.annotation.ExceptionHandler; // Annotation to handle specific exceptions
import org.springframework.web.context.request.WebRequest; // Provides access to request attributes
import java.time.LocalDateTime; // For timestamping error responses
import java.util.LinkedHashMap; // For ordered map creation
import java.util.List; // For collecting error messages
import java.util.Map; // For creating a map of error details
import java.util.stream.Collectors; // For stream operations

/**
 * Global exception handler for the Bookstore API.
 * This class uses @ControllerAdvice to provide centralized exception handling across all
 * @Controller classes. It intercepts specific exceptions thrown by controllers or services
 * and returns a standardized error response.
 */
@ControllerAdvice // Enables this class to handle exceptions globally across the application
public class GlobalExceptionHandler {

    /**
     * Handles {@link BookNotFoundException}.
     * This method is invoked when a BookNotFoundException is thrown, typically when a client
     * requests a book that does not exist in the database.
     *
     * @param ex The {@link BookNotFoundException} that was thrown.
     * @param request The current web request.
     * @return A {@link ResponseEntity} containing a structured error response and an HTTP status of 404 Not Found.
     */
    @ExceptionHandler(BookNotFoundException.class) // Specifies that this method handles BookNotFoundException
    public ResponseEntity<Object> handleBookNotFoundException(BookNotFoundException ex, WebRequest request) {
        Map<String, Object> body = new LinkedHashMap<>(); // Use LinkedHashMap to maintain insertion order
        body.put("timestamp", LocalDateTime.now()); // Add current time
        body.put("status", HttpStatus.NOT_FOUND.value()); // Add HTTP status code (404)
        body.put("error", "Not Found"); // Add general error message
        body.put("message", ex.getMessage()); // Add the specific exception message
        body.put("path", request.getDescription(false)); // Add the request URI

        return new ResponseEntity<>(body, HttpStatus.NOT_FOUND); // Return 404 Not Found status
    }

    /**
     * Handles {@link MethodArgumentNotValidException}.
     * This method is invoked when validation fails for method arguments annotated with @Valid
     * (e.g., when creating or updating a Book with invalid data).
     *
     * @param ex The {@link MethodArgumentNotValidException} that was thrown.
     * @param request The current web request.
     * @return A {@link ResponseEntity} containing a structured error response with validation details
     *         and an HTTP status of 400 Bad Request.
     */
    @ExceptionHandler(MethodArgumentNotValidException.class) // Specifies that this method handles validation exceptions
    public ResponseEntity<Object> handleValidationExceptions(MethodArgumentNotValidException ex, WebRequest request) {
        Map<String, Object> body = new LinkedHashMap<>();
        body.put("timestamp", LocalDateTime.now());
        body.put("status", HttpStatus.BAD_REQUEST.value()); // Add HTTP status code (400)
        body.put("error", "Bad Request");

        // Collect all validation error messages
        List<String> errors = ex.getBindingResult()
                .getFieldErrors() // Get field-specific errors
                .stream()
                .map(error -> error.getField() + ": " + error.getDefaultMessage()) // Format each error
                .collect(Collectors.toList()); // Collect into a list

        body.put("message", "Validation failed"); // General message for validation errors
        body.put("details", errors); // Add the list of detailed validation errors
        body.put("path", request.getDescription(false));

        return new ResponseEntity<>(body, HttpStatus.BAD_REQUEST); // Return 400 Bad Request status
    }

    // You can add more @ExceptionHandler methods for other types of exceptions as needed,
    // such as DataIntegrityViolationException, IllegalArgumentException, etc.,
    // each returning an appropriate HttpStatus and error message structure.
}
