/**
 * This class is a Spring Service component.
 * Services typically encapsulate business logic and are called by controllers.
 * The @Service annotation marks this class as a Spring-managed component, meaning
 * Spring will automatically detect it and manage its lifecycle (e.g., creating an instance).
 */
@Service
public class GreetingService {

    // A simple counter to generate unique IDs for our greetings.
    // AtomicLong is used for thread-safe incrementing, which is important in web applications.
    private final AtomicLong counter = new AtomicLong();

    /**
     * This method generates and returns a Greeting object with "Hello, World!" message.
     * In a real-world application, this method might perform more complex operations
     * like fetching data from a database, performing calculations, or calling other services.
     * @return A Greeting object containing a unique ID and the "Hello, World!" message.
     */
    public Greeting getHelloWorldGreeting() {
        // Increment the counter to get a new unique ID for the greeting.
        long newId = counter.incrementAndGet();
        // Create and return a new Greeting object.
        return new Greeting(newId, "Hello, World!");
    }
}
