package com.example.todoapp.model;

import javax.persistence.*;
import java.util.HashSet;
import java.util.Set;

// Represents a user in the application. This is an Entity that maps to a database table.
@Entity
@Table(name = "users") // Good practice to explicitly name tables, especially for 'user' which can be a reserved keyword
public class User {

    // Primary key for the User entity, automatically generated.
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    // User's unique username, cannot be null and must be unique.
    @Column(nullable = false, unique = true)
    private String username;

    // User's password, stored as a hashed string.
    @Column(nullable = false)
    private String password;

    // Roles assigned to the user, e.g., "USER", "ADMIN".
    // Stored as a set of strings in a separate join table.
    @ElementCollection(fetch = FetchType.EAGER) // Fetch roles eagerly when user is loaded
    @CollectionTable(name = "user_roles", joinColumns = @JoinColumn(name = "user_id"))
    @Column(name = "role")
    private Set<String> roles = new HashSet<>();

    // No-argument constructor is required by JPA.
    public User() {}

    // Constructor to create a new User object.
    public User(String username, String password) {
        this.username = username;
