package com.example.todoapp.service;

import com.example.todoapp.model.TodoItem;
import com.example.todoapp.model.User;
import com.example.todoapp.repository.TodoItemRepository;
import com.example.todoapp.repository.UserRepository;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.stereotype.Service;

import java.time.LocalDate;
import java.util.List;
import java.util.Optional;

// Service layer for TodoItem-related business logic.
// Contains methods to perform CRUD operations on todo items, ensuring user ownership.
@Service
public class TodoItemService {

    private final TodoItemRepository todoItemRepository;
    private final UserRepository userRepository; // To link todo items to users

    // Constructor injection for TodoItemRepository and UserRepository.
    public TodoItemService(TodoItemRepository todoItemRepository, UserRepository userRepository) {
        this.todoItemRepository = todoItemRepository;
        this.userRepository = userRepository;
    }

    // Retrieves the current authenticated user's username from the SecurityContext.
    private String getCurrentUsername() {
        Authentication authentication = SecurityContextHolder.getContext().getAuthentication();
        if (authentication != null && authentication.isAuthenticated()) {
            return authentication.getName(); // Returns the username of the currently logged-in user
        }
        throw new IllegalStateException("User not authenticated.");
    }

    // Retrieves the current authenticated user object.
    private User getCurrentUser() {
        String username = getCurrentUsername();
        return userRepository.findByUsername(username)
                .orElseThrow(() -> new RuntimeException("Authenticated user not found in database."));
    }

    // Creates a new todo item for the current authenticated user.
    public TodoItem createTodoItem(String title, String description, LocalDate dueDate) {
        User currentUser = getCurrentUser();
        TodoItem newTodo = new TodoItem(title, description, dueDate, currentUser);
        return todoItemRepository.save(newTodo);
    }

    // Retrieves all todo items for the current authenticated user.
    public List<TodoItem> getAllTodoItemsForCurrentUser() {
        User currentUser = getCurrentUser();
        return todoItemRepository.findByUserId(currentUser.getId());
    }

    // Retrieves a specific todo item by its ID, ensuring it belongs to the current user.
    public Optional<TodoItem> getTodoItemByIdForCurrentUser(Long id) {
        User currentUser = getCurrentUser();
        return todoItemRepository.findByIdAndUserId(id, currentUser.getId());
    }

    // Updates an existing todo item, ensuring it belongs to the current user.
    // Returns the updated todo item, or an empty Optional if not found/not owned.
    public Optional<TodoItem> updateTodoItem(Long id, String title, String description, Boolean completed, LocalDate dueDate) {
        User currentUser = getCurrentUser();
        Optional<TodoItem> existingTodo = todoItemRepository.findByIdAndUserId(id, currentUser.getId());

        if (existingTodo.isPresent()) {
            TodoItem todoToUpdate = existingTodo.get();
            if (title != null) todoToUpdate.setTitle(title);
            if (description != null) todoToUpdate.setDescription(description);
            if (completed != null) todoToUpdate.setCompleted(completed);
            if (dueDate != null) todoToUpdate.setDueDate(dueDate);
            return Optional.of(todoItemRepository.save(todoToUpdate));
        }
        return Optional.empty();
    }

    // Deletes a specific todo item by its ID, ensuring it belongs to the current user.
    // Returns true if deleted, false if not found or not owned.
    public boolean deleteTodoItem(Long id) {
        User currentUser = getCurrentUser();
        Optional<TodoItem> todoToDelete = todoItemRepository.findByIdAndUserId(id, currentUser.getId());

        if (todoToDelete.isPresent()) {
            todoItemRepository.delete(todoToDelete.get());
            return true;
        }
        return false;
    }
}
