package com.example.todoapp.config;

import com.example.todoapp.service.CustomUserDetailsService;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.authentication.AuthenticationManager;
import org.springframework.security.config.annotation.authentication.builders.AuthenticationManagerBuilder;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
import org.springframework.security.config.annotation.web.configuration.WebSecurityConfigurerAdapter;
import org.springframework.security.config.http.SessionCreationPolicy;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;

// Marks this class as a Spring configuration class.
@Configuration
// Enables Spring Security's web security features.
@EnableWebSecurity
public class SecurityConfig extends WebSecurityConfigurerAdapter {

    private final CustomUserDetailsService customUserDetailsService;
    private final JwtRequestFilter jwtRequestFilter;

    // Constructor injection for CustomUserDetailsService and JwtRequestFilter.
    public SecurityConfig(CustomUserDetailsService customUserDetailsService, JwtRequestFilter jwtRequestFilter) {
        this.customUserDetailsService = customUserDetailsService;
        this.jwtRequestFilter = jwtRequestFilter;
    }

    // Configures how users are authenticated (e.g., from database).
    @Override
    protected void configure(AuthenticationManagerBuilder auth) throws Exception {
        // Tells Spring Security to use our CustomUserDetailsService and PasswordEncoder for authentication.
        auth.userDetailsService(customUserDetailsService).passwordEncoder(passwordEncoder());
    }

    // Configures the security rules for HTTP requests.
    @Override
    protected void configure(HttpSecurity http) throws Exception {
        http
            .csrf().disable() // Disable CSRF for REST APIs (stateless)
            .authorizeRequests()
                // Allow public access to authentication endpoints
                .antMatchers("/auth/**").permitAll()
                // Allow access to H2 console for development
                .antMatchers("/h2-console/**").permitAll()
                // Require authentication for all other API endpoints
                .antMatchers("/api/**").authenticated()
                .anyRequest().authenticated() // All other requests require authentication
            .and()
            // Make sure we use stateless session; session won't be used to store user's state.
            .sessionManagement().sessionCreationPolicy(SessionCreationPolicy.STATELESS)
            .and()
            // Add our custom JWT filter before Spring Security's UsernamePasswordAuthenticationFilter
            .addFilterBefore(jwtRequestFilter, UsernamePasswordAuthenticationFilter.class);

        // Required for H2 console to work with Spring Security
        http.headers().frameOptions().disable();
    }

    // Exposes the AuthenticationManager as a Bean.
    // This allows it to be autowired into other components (e.g., AuthController).
    @Bean
    @Override
    public AuthenticationManager authenticationManagerBean() throws Exception {
        return super.authenticationManagerBean();
    }

    // Defines a PasswordEncoder bean for hashing passwords.
    // BCrypt is a strong hashing algorithm recommended for passwords.
    @Bean
    public PasswordEncoder passwordEncoder() {
        return new BCryptPasswordEncoder();
    }
}
