package com.example.todoapp.config;

import com.example.todoapp.service.CustomUserDetailsService;
import com.example.todoapp.util.JwtUtil;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.security.core.userdetails.UserDetails;
import org.springframework.security.web.authentication.WebAuthenticationDetailsSource;
import org.springframework.stereotype.Component;
import org.springframework.web.filter.OncePerRequestFilter;

import javax.servlet.FilterChain;
import javax.servlet.ServletException;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.io.IOException;

// This filter intercepts every incoming HTTP request to validate JWT tokens.
// It extends OncePerRequestFilter to ensure it's executed only once per request.
@Component
public class JwtRequestFilter extends OncePerRequestFilter {

    private final CustomUserDetailsService customUserDetailsService;
    private final JwtUtil jwtUtil;

    // Constructor injection for CustomUserDetailsService and JwtUtil.
    public JwtRequestFilter(CustomUserDetailsService customUserDetailsService, JwtUtil jwtUtil) {
        this.customUserDetailsService = customUserDetailsService;
        this.jwtUtil = jwtUtil;
    }

    // This method contains the logic to inspect the request for a JWT.
    @Override
    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain chain)
            throws ServletException, IOException {

        // Get the "Authorization" header from the request.
        final String authorizationHeader = request.getHeader("Authorization");

        String username = null;
        String jwt = null;

        // Check if the header exists and starts with "Bearer ".
        if (authorizationHeader != null && authorizationHeader.startsWith("Bearer ")) {
            jwt = authorizationHeader.substring(7); // Extract the JWT token (after "Bearer ")
            username = jwtUtil.extractUsername(jwt); // Extract username from the token
        }

        // If username is found and no authentication is currently set in the SecurityContext.
        if (username != null && SecurityContextHolder.getContext().getAuthentication() == null) {
            // Load user details from our custom service.
            UserDetails userDetails = this.customUserDetailsService.loadUserByUsername(username);

            // Validate the token.
            if (jwtUtil.validateToken(jwt, userDetails)) {
                // If token is valid, create an authentication token.
                UsernamePasswordAuthenticationToken usernamePasswordAuthenticationToken =
                        new UsernamePasswordAuthenticationToken(userDetails, null, userDetails.getAuthorities());
                // Set authentication details from the HTTP request.
                usernamePasswordAuthenticationToken.setDetails(new WebAuthenticationDetailsSource().buildDetails(request));
                // Set the authentication in the SecurityContext.
                // This means the current user is now authenticated for this request.
                SecurityContextHolder.getContext().setAuthentication(usernamePasswordAuthenticationToken);
            }
        }
        // Continue the filter chain.
        chain.doFilter(request, response);
    }
}
