package com.example.todoapp.util;

import io.jsonwebtoken.Claims;
import io.jsonwebtoken.Jwts;
import io.jsonwebtoken.SignatureAlgorithm;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.security.core.userdetails.UserDetails;
import org.springframework.stereotype.Component;

import java.util.Date;
import java.util.HashMap;
import java.util.Map;
import java.util.function.Function;

// Utility class for JWT (JSON Web Token) operations like generation and validation.
@Component
public class JwtUtil {

    // Inject the JWT secret key from application.properties.
    @Value("${jwt.secret}")
    private String SECRET_KEY;

    // Inject the JWT expiration time from application.properties (in milliseconds).
    @Value("${jwt.expiration}")
    private long EXPIRATION_TIME;

    // Extracts the username from a JWT token.
    public String extractUsername(String token) {
        return extractClaim(token, Claims::getSubject);
    }

    // Extracts the expiration date from a JWT token.
    public Date extractExpiration(String token) {
        return extractClaim(token, Claims::getExpiration);
    }

    // Generic method to extract a specific claim from the token.
    public <T> T extractClaim(String token, Function<Claims, T> claimsResolver) {
        final Claims claims = extractAllClaims(token);
        return claimsResolver.apply(claims);
    }

    // Extracts all claims (payload) from the token using the secret key.
    private Claims extractAllClaims(String token) {
        return Jwts.parser().setSigningKey(SECRET_KEY).parseClaimsJws(token).getBody();
    }

    // Checks if the token has expired.
    private Boolean isTokenExpired(String token) {
        return extractExpiration(token).before(new Date());
    }

    // Generates a JWT token for a given UserDetails.
    public String generateToken(UserDetails userDetails) {
        Map<String, Object> claims = new HashMap<>();
        // You can add additional claims here if needed, e.g., user roles.
        // For now, we only store the subject (username).
        return createToken(claims, userDetails.getUsername());
    }

    // Creates the JWT token using claims, subject, current time, expiration time, and signing algorithm.
    private String createToken(Map<String, Object> claims, String subject) {
        return Jwts.builder()
                .setClaims(claims) // Custom claims
                .setSubject(subject) // User identifier (username)
                .setIssuedAt(new Date(System.currentTimeMillis())) // Token creation time
                .setExpiration(new Date(System.currentTimeMillis() + EXPIRATION_TIME)) // Token expiration time
                .signWith(SignatureAlgorithm.HS256, SECRET_KEY) // Signing algorithm and secret key
                .compact(); // Builds the token
    }

    // Validates a JWT token against UserDetails.
    public Boolean validateToken(String token, UserDetails userDetails) {
        final String username = extractUsername(token);
        // Token is valid if username matches and it's not expired.
        return (username.equals(userDetails.getUsername()) && !isTokenExpired(token));
    }
}
