package com.example.todoapp.controller;

import com.example.todoapp.dto.AuthRequest;
import com.example.todoapp.dto.AuthResponse;
import com.example.todoapp.service.CustomUserDetailsService;
import com.example.todoapp.service.UserService;
import com.example.todoapp.util.JwtUtil;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.security.authentication.AuthenticationManager;
import org.springframework.security.authentication.BadCredentialsException;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.userdetails.UserDetails;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

// REST Controller for user authentication and registration.
@RestController
@RequestMapping("/auth") // All endpoints in this controller start with /auth
public class AuthController {

    private final AuthenticationManager authenticationManager;
    private final CustomUserDetailsService customUserDetailsService;
    private final JwtUtil jwtUtil;
    private final UserService userService;

    // Constructor injection for required services and utilities.
    public AuthController(AuthenticationManager authenticationManager,
                          CustomUserDetailsService customUserDetailsService,
                          JwtUtil jwtUtil,
                          UserService userService) {
        this.authenticationManager = authenticationManager;
        this.customUserDetailsService = customUserDetailsService;
        this.jwtUtil = jwtUtil;
        this.userService = userService;
    }

    // Endpoint for user registration.
    // Takes AuthRequest (username, password) and creates a new user.
    @PostMapping("/register")
    public ResponseEntity<?> registerUser(@RequestBody AuthRequest authRequest) {
        try {
            userService.registerNewUser(authRequest.getUsername(), authRequest.getPassword());
            // If registration is successful, automatically log in the user and return a JWT.
            return createAuthenticationToken(authRequest);
        } catch (RuntimeException e) {
            // If username already exists or other registration error.
            return ResponseEntity.status(HttpStatus.CONFLICT).body(e.getMessage());
        }
    }

    // Endpoint for user login.
    // Takes AuthRequest (username, password) and returns a JWT on successful authentication.
    @PostMapping("/login")
    public ResponseEntity<?> createAuthenticationToken(@RequestBody AuthRequest authRequest) {
        try {
            // Attempt to authenticate the user using Spring Security's AuthenticationManager.
            authenticationManager.authenticate(
                    new UsernamePasswordAuthenticationToken(authRequest.getUsername(), authRequest.getPassword())
            );
        } catch (BadCredentialsException e) {
            // If authentication fails (invalid username/password).
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body("Incorrect username or password");
        }

        // If authentication is successful, load UserDetails and generate a JWT.
        final UserDetails userDetails = customUserDetailsService
                .loadUserByUsername(authRequest.getUsername());
        final String jwt = jwtUtil.generateToken(userDetails);

        // Return the JWT token in the response.
        return ResponseEntity.ok(new AuthResponse(jwt));
    }
}
