    // GET /api/todos - Retrieve all todo items for the current authenticated user.
    @GetMapping
    public ResponseEntity<List<TodoItem>> getAllUserTodoItems() {
        List<TodoItem> todoItems = todoItemService.getAllTodoItemsForCurrentUser();
        return ResponseEntity.ok(todoItems);
    }

    // GET /api/todos/{id} - Retrieve a specific todo item by ID for the current user.
    @GetMapping("/{id}")
    public ResponseEntity<TodoItem> getTodoItemById(@PathVariable Long id) {
        return todoItemService.getTodoItemByIdForCurrentUser(id)
                .map(ResponseEntity::ok) // If found, return 200 OK with the item
                .orElse(ResponseEntity.notFound().build()); // If not found, return 404 Not Found
    }

    // POST /api/todos - Create a new todo item for the current user.
    @PostMapping
    public ResponseEntity<TodoItem> createTodoItem(@RequestBody TodoItemRequest request) {
        // Basic validation: title is required.
        if (request.getTitle() == null || request.getTitle().trim().isEmpty()) {
            return ResponseEntity.badRequest().build();
        }
        TodoItem newTodo = todoItemService.createTodoItem(
                request.getTitle(),
                request.getDescription(),
                request.getDueDate()
        );
        // Return 201 Created status with the newly created item.
        return ResponseEntity.status(HttpStatus.CREATED).body(newTodo);
    }

    // PUT /api/todos/{id} - Update an existing todo item by ID for the current user.
    @PutMapping("/{id}")
    public ResponseEntity<TodoItem> updateTodoItem(@PathVariable Long id, @RequestBody TodoItemRequest request) {
        return todoItemService.updateTodoItem(
                id,
                request.getTitle(),
                request.getDescription(),
                request.getCompleted(),
                request.getDueDate()
        )
                .map(ResponseEntity::ok) // If updated, return 200 OK with the updated item
                .orElse(ResponseEntity.notFound().build()); // If not found/not owned, return 404 Not Found
    }

    // DELETE /api/todos/{id} - Delete a todo item by ID for the current user.
    @DeleteMapping("/{id}")
    public ResponseEntity<Void> deleteTodoItem(@PathVariable Long id) {
        if (todoItemService.deleteTodoItem(id)) {
            // If deleted successfully, return 204 No Content.
            return ResponseEntity.noContent().build();
        }
        // If not found/not owned, return 404 Not Found.
        return ResponseEntity.notFound().build();
    }
}
