// src/main/java/com/example/urlshortener/service/UrlShortenerService.java
package com.example.urlshortener.service;

import com.example.urlshortener.exception.UrlNotFoundException;
import com.example.urlshortener.model.UrlMapping;
import com.example.urlshortener.repository.UrlMappingRepository;
import org.springframework.stereotype.Service;

import java.security.SecureRandom;
import java.util.Optional;

/**
 * Service class responsible for the business logic of URL shortening.
 * It interacts with the repository to persist and retrieve URL mappings.
 */
@Service // Marks this class as a Spring service component.
public class UrlShortenerService {

    private final UrlMappingRepository urlMappingRepository;
    private static final String ALPHABET = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    private static final int SHORT_CODE_LENGTH = 6;
    private static final SecureRandom random = new SecureRandom();

    // Constructor-based dependency injection. Spring automatically provides an instance of UrlMappingRepository.
    public UrlShortenerService(UrlMappingRepository urlMappingRepository) {
        this.urlMappingRepository = urlMappingRepository;
    }

    /**
     * Creates a short URL for a given original URL.
     * Generates a unique short code and saves the mapping to the database.
     *
     * @param originalUrl The long URL to shorten.
     * @return The generated short code.
     */
    public String shortenUrl(String originalUrl) {
        String shortCode;
        // Loop until a unique short code is generated
        do {
            shortCode = generateShortCode();
        } while (urlMappingRepository.findByShortCode(shortCode).isPresent()); // Check if code already exists

        UrlMapping urlMapping = new UrlMapping(originalUrl, shortCode);
        urlMappingRepository.save(urlMapping); // Save the new mapping to the database
        return shortCode;
    }

    /**
     * Retrieves the original URL associated with a given short code.
     *
     * @param shortCode The short code to look up.
     * @return The original URL.
     * @throws UrlNotFoundException If no mapping is found for the given short code.
     */
    public String getOriginalUrl(String shortCode) {
        Optional<UrlMapping> urlMappingOptional = urlMappingRepository.findByShortCode(shortCode);

        // If the short code is found, return its original URL.
        // Otherwise, throw a custom exception indicating the URL was not found.
        return urlMappingOptional
                .map(UrlMapping::getOriginalUrl) // If present, get the original URL
                .orElseThrow(() -> new UrlNotFoundException("URL not found for short code: " + shortCode));
    }

    /**
     * Generates a random alphanumeric short code of a fixed length.
     * This method doesn't guarantee uniqueness; uniqueness is handled in shortenUrl method.
     *
     * @return A randomly generated short code string.
     */
    private String generateShortCode() {
        StringBuilder builder = new StringBuilder(SHORT_CODE_LENGTH);
        for (int i = 0; i < SHORT_CODE_LENGTH; i++) {
            builder.append(ALPHABET.charAt(random.nextInt(ALPHABET.length())));
        }
        return builder.toString();
    }
}
