package com.example.urlshortener.controller;

import com.example.urlshortener.dto.ShortenUrlRequest;
import com.example.urlshortener.dto.ShortenUrlResponse;
import com.example.urlshortener.service.UrlShortenerService;
import jakarta.validation.Valid;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.net.URI;

/**
 * REST Controller for the URL Shortener API.
 * Handles incoming HTTP requests related to URL shortening and redirection.
 */
@RestController // Marks this class as a REST controller, meaning it handles web requests.
public class UrlShortenerController {

    private final UrlShortenerService urlShortenerService;

    // Constructor-based dependency injection. Spring automatically provides an instance of UrlShortenerService.
    public UrlShortenerController(UrlShortenerService urlShortenerService) {
        this.urlShortenerService = urlShortenerService;
    }

    /**
     * API endpoint to create a short URL.
     *
     * @param request The ShortenUrlRequest DTO containing the original URL.
     * @return A ResponseEntity containing the ShortenUrlResponse DTO with the generated short code.
     *         Returns HTTP 201 Created status upon successful creation.
     */
    @PostMapping("/api/shorten") // Maps HTTP POST requests to "/api/shorten" to this method.
    public ResponseEntity<ShortenUrlResponse> shortenUrl(@Valid @RequestBody ShortenUrlRequest request) {
        // @Valid triggers validation annotations defined in ShortenUrlRequest (e.g., @NotBlank, @Pattern).
        // @RequestBody binds the HTTP request body to the ShortenUrlRequest object.

        String originalUrl = request.getOriginalUrl();
        String shortCode = urlShortenerService.shortenUrl(originalUrl); // Call the service to shorten the URL

        // Create a response DTO containing the generated short code and original URL.
        ShortenUrlResponse response = new ShortenUrlResponse(shortCode, originalUrl);

        // Return the response with HTTP status 201 Created.
        return new ResponseEntity<>(response, HttpStatus.CREATED);
    }

    /**
     * API endpoint to redirect from a short URL to its original long URL.
     * This endpoint is typically exposed at the root or a sub-path without "api" prefix.
     *
     * @param shortCode The short code extracted from the URL path.
     * @return A ResponseEntity that issues an HTTP 302 Found redirect to the original URL.
     *         If the short code is not found, an UrlNotFoundException is thrown (handled by GlobalExceptionHandler).
     */
    @GetMapping("/{shortCode}") // Maps HTTP GET requests to any path variable after the root (e.g., "/abcde")
    public ResponseEntity<Void> redirectToOriginalUrl(@PathVariable String shortCode) {
        // @PathVariable extracts the value from the URL path into the 'shortCode' parameter.

        String originalUrl = urlShortenerService.getOriginalUrl(shortCode); // Retrieve original URL from service

        // Create HTTP Headers for redirection.
        HttpHeaders headers = new HttpHeaders();
        // Set the Location header to the original URL.
        headers.setLocation(URI.create(originalUrl));

        // Return a ResponseEntity with no body (Void), the custom headers, and HTTP status 302 Found.
        return new ResponseEntity<>(headers, HttpStatus.FOUND);
    }
}
