// UrlShortenerService.java
package com.example.urlshortener.service;

import com.example.urlshortener.model.UrlMapping;
import com.example.urlshortener.repository.UrlMappingRepository;
import org.springframework.stereotype.Service;

import java.util.Optional;
import java.util.Random;
import java.util.stream.Collectors;

/**
 * Service layer for URL shortening operations.
 * This class encapsulates the business logic for generating short codes,
 * saving URL mappings, and retrieving original URLs.
 */
@Service // Marks this class as a Spring Service component.
// Spring automatically detects this and manages it as a singleton bean in the application context.
public class UrlShortenerService {

    private final UrlMappingRepository urlMappingRepository; // Dependency on the repository for database operations.

    // Constants for short code generation.
    private static final String CHARACTERS = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    private static final int SHORT_CODE_LENGTH = 6; // Desired length of the generated short code.
    private final Random random = new Random(); // Random number generator for short code generation.

    /**
     * Constructor for dependency injection.
     * Spring automatically injects an instance of UrlMappingRepository when UrlShortenerService is created.
     */
    public UrlShortenerService(UrlMappingRepository urlMappingRepository) {
        this.urlMappingRepository = urlMappingRepository;
    }

    /**
     * Shortens a given original URL.
     * - Checks if the URL has already been shortened to avoid duplicates.
     * - Generates a unique short code.
     * - Saves the mapping to the database.
     *
     * @param originalUrl The long URL to be shortened.
     * @return The generated (or existing) unique short code.
     */
    public String shortenUrl(String originalUrl) {
        // 1. Check if the original URL already exists in our system.
        // This prevents creating multiple short codes for the same long URL.
        Optional<UrlMapping> existingMapping = urlMappingRepository.findByOriginalUrl(originalUrl);
        if (existingMapping.isPresent()) {
            // If found, return the existing short code.
            return existingMapping.get().getShortCode();
        }

        String shortCode;
        // 2. Generate a unique short code.
        // Loop until a short code is generated that doesn't already exist in the database.
        do {
            shortCode = generateRandomShortCode();
        } while (urlMappingRepository.findByShortCode(shortCode).isPresent()); // Keep trying until unique

        // 3. Create a new UrlMapping object and save it to the database.
        UrlMapping urlMapping = new UrlMapping();
        urlMapping.setOriginalUrl(originalUrl);
        urlMapping.setShortCode(shortCode);

        urlMappingRepository.save(urlMapping); // Persist the new mapping.
        return shortCode; // Return the newly generated short code.
    }

    /**
     * Retrieves the original URL associated with a given short code.
     *
     * @param shortCode The short code to look up.
     * @return The original URL.
     * @throws IllegalArgumentException if no mapping is found for the given short code.
     */
    public String getOriginalUrl(String shortCode) {
        // Find the UrlMapping by short code.
        return urlMappingRepository.findByShortCode(shortCode)
                // If found, map the Optional<UrlMapping> to Optional<String> (the original URL).
                .map(UrlMapping::getOriginalUrl)
                // If not found (Optional is empty), throw an exception.
                .orElseThrow(() -> new IllegalArgumentException("Short URL not found: " + shortCode));
    }

    /**
     * Generates a random alphanumeric string of a predefined length.
     * This method is used internally to create candidate short codes.
     *
     * @return A randomly generated short code string.
     */
    private String generateRandomShortCode() {
        return random.ints(SHORT_CODE_LENGTH, 0, CHARACTERS.length()) // Generate a stream of random indices.
                .mapToObj(CHARACTERS::charAt) // Map each index to a character from the CHARACTERS string.
                .map(Object::toString) // Convert each character to a String.
                .collect(Collectors.joining()); // Join all characters to form the final short code string.
    }
}
