// UrlShortenerController.java
package com.example.urlshortener.controller;

import com.example.urlshortener.dto.ShortenRequest;
import com.example.urlshortener.service.UrlShortenerService;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.server.ResponseStatusException;

import java.net.URI; // Used for creating the Location header for redirects.

/**
 * REST Controller for the URL shortener API.
 * This class handles incoming HTTP requests related to URL shortening and redirection.
 */
@RestController // Marks this class as a REST controller, meaning it handles web requests.
@RequestMapping("/api/v1/shortener") // Base path for all endpoints in this controller.
public class UrlShortenerController {

    private final UrlShortenerService urlShortenerService; // Dependency on the service layer.

    /**
     * Constructor for dependency injection.
     * Spring automatically injects an instance of UrlShortenerService when UrlShortenerController is created.
     */
    public UrlShortenerController(UrlShortenerService urlShortenerService) {
        this.urlShortenerService = urlShortenerService;
    }

    /**
     * API endpoint to shorten a given URL.
     * Accepts a POST request with the original URL in the request body.
     *
     * Example request:
     * POST /api/v1/shortener/shorten
     * Content-Type: application/json
     * Body: {"originalUrl": "https://www.example.com/very/long/url/path"}
     *
     * Example response (Success 200 OK):
     * abc123
     *
     * Example response (Error 500 Internal Server Error):
     * Error shortening URL: Some error message
     *
     * @param request A ShortenRequest DTO containing the original URL.
     * @return A ResponseEntity containing the generated short code string or an error message.
     */
    @PostMapping("/shorten") // Maps HTTP POST requests to "/api/v1/shortener/shorten".
    public ResponseEntity<String> shortenUrl(@RequestBody ShortenRequest request) {
        try {
            // Call the service layer to perform the shortening logic.
            String shortCode = urlShortenerService.shortenUrl(request.getOriginalUrl());
            // Return the generated short code with a 200 OK status.
            // In a more complete application, you might return the full shortened URL (e.g., "http://localhost:8080/abc123").
            return ResponseEntity.ok(shortCode);
        } catch (Exception e) {
            // Catch any exceptions during the shortening process.
            // For simplicity, we return a generic 500 Internal Server Error.
            // In a real application, you would handle specific exceptions (e.g., URL validation errors)
            // with more specific HTTP status codes (e.g., 400 Bad Request).
            return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR)
                    .body("Error shortening URL: " + e.getMessage());
        }
    }

    /**
     * API endpoint to retrieve the original URL and redirect the client to it.
     * Accepts a GET request with the short code as a path variable.
     *
     * Example request:
     * GET /api/v1/shortener/abc123
     *
     * Example response (Success 302 Found):
     * HTTP/1.1 302 Found
     * Location: https://www.example.com/very/long/url/path
     *
     * Example response (Not Found 404):
     * HTTP/1.1 404 Not Found
     *
     * @param shortCode The short code to look up.
     * @return A ResponseEntity that triggers a 302 Found redirect to the original URL.
     * @throws ResponseStatusException if the short code is not found, resulting in a 404 Not Found.
     */
    @GetMapping("/{shortCode}") // Maps HTTP GET requests to "/api/v1/shortener/{shortCode}".
    public ResponseEntity<Void> redirectToOriginalUrl(@PathVariable String shortCode) {
        try {
            // Call the service layer to get the original URL for the given short code.
            String originalUrl = urlShortenerService.getOriginalUrl(shortCode);

            // Return a 302 Found status with the Location header set to the original URL.
            // This tells the client (browser) to automatically navigate to the original URL.
            return ResponseEntity.status(HttpStatus.FOUND) // HTTP 302 Found
                    .location(URI.create(originalUrl)) // Set the Location header for redirection
                    .build(); // Build the ResponseEntity.
        } catch (IllegalArgumentException e) {
            // If the UrlShortenerService throws an IllegalArgumentException (meaning the short code was not found),
            // we translate it into an HTTP 404 Not Found response.
            throw new ResponseStatusException(HttpStatus.NOT_FOUND, e.getMessage());
        }
    }
}
