// src/main/java/com/example/urlshortener/service/UrlShortenerService.java
package com.example.urlshortener.service;

import com.example.urlshortener.model.UrlMapping; // Import our model class
import org.springframework.stereotype.Service;

import java.security.SecureRandom;
import java.util.concurrent.ConcurrentHashMap;
import java.util.Optional;

// This is our service layer, responsible for the business logic of URL shortening.
// @Service annotation marks this class as a Spring Service component.
// Spring will automatically detect and manage this component and create a single instance (singleton).
@Service
public class UrlShortenerService {

    // A thread-safe map to store our URL mappings in memory.
    // Key: shortCode (String), Value: UrlMapping object.
    // Using ConcurrentHashMap ensures thread safety when multiple requests
    // try to shorten URLs simultaneously, which is important for multi-threaded applications.
    // Storing UrlMapping objects instead of just strings allows us to easily extend
    // the functionality (e.g., store creation date, click count, user ID, etc.) later.
    private final ConcurrentHashMap<String, UrlMapping> urlStore = new ConcurrentHashMap<>();

    // Characters used for generating random short codes (alphanumeric).
    private static final String ALPHANUMERIC_CHARS = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    // Length of the generated short code. A typical length is 6-8 characters.
    private static final int SHORT_CODE_LENGTH = 7;
    // SecureRandom is used for generating cryptographically strong random numbers,
    // which is better than java.util.Random for security-sensitive contexts like this.
    private final SecureRandom random = new SecureRandom();

    /**
     * Shortens a given long URL and stores the mapping.
     *
     * @param longUrl The original URL to be shortened.
     * @return The generated short code for the URL.
     */
    public String shortenUrl(String longUrl) {
        // Generate a unique short code.
        String shortCode = generateUniqueShortCode();

        // Create a new UrlMapping object with the generated short code and the original long URL.
        UrlMapping urlMapping = new UrlMapping(shortCode, longUrl);

        // Store the mapping in our in-memory store.
        // In a real application, this step would involve saving the `urlMapping` object to a database.
        urlStore.put(shortCode, urlMapping);

        // Return the generated short code. The controller will use this to build the full short URL.
        return shortCode;
    }

    /**
     * Retrieves the original long URL associated with a given short code.
     *
     * @param shortCode The short code to look up.
     * @return An Optional containing the long URL string if found, or an empty Optional if not found.
     *         Using Optional is a modern Java way to explicitly handle cases where a value might be absent.
     */
    public Optional<String> getLongUrl(String shortCode) {
        // Retrieve the UrlMapping object from the store using the short code as the key.
        // If no mapping is found, `urlStore.get()` returns null.
        // `Optional.ofNullable()` safely wraps the result.
        return Optional.ofNullable(urlStore.get(shortCode))
                // If a UrlMapping object is present, we map it to its longUrl string.
                .map(UrlMapping::getLongUrl);
    }

    /**
     * Generates a unique short code.
     * It ensures that the generated code does not already exist in our store to prevent collisions.
     *
     * @return A unique short code string.
     */
    private String generateUniqueShortCode() {
        String shortCode;
        // Loop indefinitely until a truly unique short code is generated.
        // This is important to avoid collisions in our in-memory store (or database).
        // The probability of collision is very low with a 7-character alphanumeric code,
        // but checking ensures correctness.
        do {
            shortCode = generateRandomShortCode();
        } while (urlStore.containsKey(shortCode)); // Check if this generated code is already in use.
        return shortCode;
    }

    /**
     * Generates a random alphanumeric string of a predefined length (`SHORT_CODE_LENGTH`).
     *
     * @return A random short code string.
     */
    private String generateRandomShortCode() {
        StringBuilder sb = new StringBuilder(SHORT_CODE_LENGTH);
        for (int i = 0; i < SHORT_CODE_LENGTH; i++) {
            // Pick a random character from our allowed alphanumeric characters string.
            sb.append(ALPHANUMERIC_CHARS.charAt(random.nextInt(ALPHANUMERIC_CHARS.length())));
        }
        return sb.toString();
    }
}
