@RequestMapping("/api/v1/shortener")
public class UrlShortenerController {

    // We inject our UrlShortenerService here.
    // Spring's @Autowired (or constructor injection, as used here) automatically finds
    // and provides an instance of the service, which is managed by Spring's IoC container.
    private final UrlShortenerService urlShortenerService;

    // Constructor injection is the recommended way to inject dependencies in Spring.
    // Spring will automatically provide the UrlShortenerService instance when it creates
    // an instance of UrlShortenerController.
    public UrlShortenerController(UrlShortenerService urlShortenerService) {
        this.urlShortenerService = urlShortenerService;
    }

    /**
     * Endpoint to shorten a given long URL.
     *
     * HTTP Method: POST
     * Path: /api/v1/shortener/shorten
     * Request Body: JSON object containing "longUrl"
     *               (e.g., `{"longUrl": "https://example.com/very/long/url"}`)
     * Response: JSON object containing "shortUrl"
     *           (e.g., `{"shortUrl": "http://localhost:8080/abcDEFg"}`)
