import org.springframework.web.bind.annotation.GetMapping; // For handling GET requests
import org.springframework.web.bind.annotation.PathVariable; // For extracting path variables
import org.springframework.web.bind.annotation.RestController; // Combination of @Controller and @ResponseBody

import java.net.URI; // For constructing URI for redirection

// This controller handles the redirection logic for the shortened URLs.
// It's common practice to have the redirection endpoint at the root path,
// hence it's in a separate controller without a specific `@RequestMapping` base path,
// allowing URLs like `http://localhost:8080/abcDEFg`.
@RestController
public class RedirectController {

    // Inject our UrlShortenerService.
    private final UrlShortenerService urlShortenerService;

    // Constructor injection for the service dependency.
    public RedirectController(UrlShortenerService urlShortenerService) {
        this.urlShortenerService = urlShortenerService;
    }

    /**
     * Endpoint to redirect from a short code to the original long URL.
     *
     * HTTP Method: GET
     * Path: /{shortCode} (e.g., `http://localhost:8080/abcDEFg`)
     * Response: HTTP 302 Found redirect to the original long URL, or HTTP 404 Not Found.
     *
     * @param shortCode The short code extracted from the URL path (e.g., "abcDEFg").
     *                  @PathVariable maps a part of the URL path to a method parameter.
     * @return ResponseEntity that performs an HTTP redirect or returns a 404 Not Found error.
     */
    @GetMapping("/{shortCode}")
    // ResponseEntity<Void> is used because we don't return a body for a redirect.
    public ResponseEntity<Void> redirectToLongUrl(@PathVariable String shortCode) {
        // Try to retrieve the original long URL using the short code from our service.
        return urlShortenerService.getLongUrl(shortCode)
                // If the Optional contains a value (i.e., the long URL was found):
                .map(longUrl -> {
                    // Create an HTTP 302 Found response.
                    // This status code tells the client (browser) that the requested resource
                    // has been temporarily moved to a different URI.
                    return ResponseEntity
                            .status(HttpStatus.FOUND) // Set HTTP status to 302 Found
                            .location(URI.create(longUrl)) // Set the "Location" header to the original long URL
                            .build(); // Build the response
                })
                // If the Optional is empty (i.e., the short code was not found):
                .orElseGet(() -> {
                    // Return an HTTP 404 Not Found response.
                    // This indicates that the requested short code does not correspond to any known URL.
                    return ResponseEntity.notFound().build();
                });
    }
}
