@Entity // Marks this class as a JPA entity, meaning it maps to a database table.
@Table(name = "urls") // Specifies the name of the database table for this entity.
public class URL {

    @Id // Marks this field as the primary key for the entity.
    @GeneratedValue(strategy = GenerationType.IDENTITY) // Configures the primary key to be auto-generated by the database.
    private Long id;

    @Column(nullable = false, unique = true, length = 2048) // Maps this field to a database column.
                                                         // 'nullable = false' means it cannot be empty.
                                                         // 'unique = true' ensures no two URLs have the same original URL (optional, can be removed if duplicates allowed).
                                                         // 'length' specifies max length for database column.
    private String originalUrl;

    @Column(nullable = false, unique = true, length = 10) // 'shortCode' must be unique and not null.
                                                       // 'length' is set for our 8-character short codes + some buffer.
    private String shortCode;

    @Column(nullable = false) // 'creationDate' cannot be empty.
    private LocalDateTime creationDate;

    // Default constructor is required by JPA.
    public URL() {
    }

    /**
     * Constructor to create a new URL object.
     * @param originalUrl The long URL that needs to be shortened.
     * @param shortCode The unique, short identifier for the URL.
     * @param creationDate The timestamp when the URL was shortened.
     */
    public URL(String originalUrl, String shortCode, LocalDateTime creationDate) {
        this.originalUrl = originalUrl;
        this.shortCode = shortCode;
        this.creationDate = creationDate;
    }

    // --- Getters and Setters for all fields ---
    // These methods allow us to access and modify the private fields of the URL object.

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public String getOriginalUrl() {
        return originalUrl;
    }

    public void setOriginalUrl(String originalUrl) {
        this.originalUrl = originalUrl;
    }

    public String getShortCode() {
        return shortCode;
    }

    public void setShortCode(String shortCode) {
        this.shortCode = shortCode;
    }

    public LocalDateTime getCreationDate() {
        return creationDate;
    }

    public void setCreationDate(LocalDateTime creationDate) {
        this.creationDate = creationDate;
    }

    // Optional: Override toString() for better logging/debugging.
    @Override
