// src/main/java/com/example/urlshortener/service/URLShortenerService.java
package com.example.urlshortener.service;

import com.example.urlshortener.model.URL;
import com.example.urlshortener.repository.URLRepository;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import java.time.LocalDateTime;
import java.util.Optional;
import java.util.Random;

/**
 * Service layer for URL shortening business logic.
 * This class encapsulates the core functionality for generating short URLs
 * and retrieving original URLs.
 */
@Service // Marks this class as a Spring Service component, making it eligible for component scanning.
public class URLShortenerService {

    private final URLRepository urlRepository; // Dependency on URLRepository for data access.
    private final Random random = new Random(); // Used for generating random short codes.
    private static final String ALPHANUMERIC_CHARS = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    private static final int SHORT_CODE_LENGTH = 8; // Desired length for our short codes.

    /**
     * Constructor for URLShortenerService.
     * Spring automatically injects an instance of URLRepository because of @Autowired.
     * @param urlRepository The repository for URL data operations.
     */
    @Autowired
    public URLShortenerService(URLRepository urlRepository) {
        this.urlRepository = urlRepository;
    }

    /**
     * Generates a unique short code.
     * This is a simple implementation; in a production system, you'd want to ensure
     * collision avoidance (e.g., check if the generated code already exists and retry).
     * For this minimal example, we'll assume uniqueness for generated codes or handle
     * potential (though unlikely for 8 chars) collisions by database constraint.
     * @return A randomly generated alphanumeric short code.
     */
    private String generateShortCode() {
        StringBuilder sb = new StringBuilder(SHORT_CODE_LENGTH);
        for (int i = 0; i < SHORT_CODE_LENGTH; i++) {
            sb.append(ALPHANUMERIC_CHARS.charAt(random.nextInt(ALPHANUMERIC_CHARS.length())));
        }
        return sb.toString();
    }

    /**
     * Shortens a given original URL.
     * - Generates a unique short code.
     * - Saves the original URL and the short code to the database.
     * @param originalUrl The long URL to be shortened.
     * @return The generated short code.
     */
    public String shortenUrl(String originalUrl) {
        String shortCode;
        // In a more robust system, you would loop here and regenerate shortCode
        // if urlRepository.findByShortCode(shortCode).isPresent() is true.
        // For simplicity, we assume generateShortCode is sufficiently unique for this demo.
        shortCode = generateShortCode();

        URL url = new URL(originalUrl, shortCode, LocalDateTime.now());
        urlRepository.save(url); // Save the new URL entity to the database.
        return shortCode;
    }

    /**
     * Retrieves the original URL corresponding to a given short code.
     * @param shortCode The short code to look up.
     * @return An Optional containing the original URL string if found,
     *         or an empty Optional if no URL is associated with the short code.
     */
    public Optional<String> getOriginalUrl(String shortCode) {
        // Use the repository to find the URL by its short code.
        // Optional is a good way to handle cases where the URL might not be found,
        // preventing NullPointerExceptions.
        return urlRepository.findByShortCode(shortCode)
                .map(URL::getOriginalUrl); // If found, map the URL object to its originalUrl string.
    }
}
