package com.example.urlshortener.controller;

import com.example.urlshortener.service.URLShortenerService;
import jakarta.servlet.http.HttpServletResponse;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;

import java.io.IOException;
import java.util.HashMap;
import java.util.Map;

/**
 * REST Controller for the URL Shortener API.
 * This class handles incoming HTTP requests related to URL shortening and redirection.
 */
@RestController // Marks this class as a REST controller, meaning it handles web requests and returns data directly.
@RequestMapping("/") // Base path for all endpoints in this controller. We'll specify more specific paths below.
public class URLShortenerController {

    private final URLShortenerService urlShortenerService; // Dependency on URLShortenerService.

    /**
     * Constructor for URLShortenerController.
     * Spring automatically injects an instance of URLShortenerService.
     * @param urlShortenerService The service layer for URL shortening operations.
     */
    @Autowired
    public URLShortenerController(URLShortenerService urlShortenerService) {
        this.urlShortenerService = urlShortenerService;
    }

    /**
     * API endpoint to shorten a long URL.
     * Accessible via POST requests to "/api/shorten".
     *
     * @param requestBody A Map containing the "originalUrl" string from the request JSON body.
     *                    Example request body: {"originalUrl": "https://www.example.com/very/long/url"}
     * @return A ResponseEntity containing a JSON object with the "shortUrl" (e.g., {"shortUrl": "http://localhost:8080/abcde123"})
     *         and HTTP status 201 (Created) if successful.
     *         Returns HTTP status 400 (Bad Request) if "originalUrl" is missing.
     */
    @PostMapping("/api/shorten")
    public ResponseEntity<Map<String, String>> shortenUrl(@RequestBody Map<String, String> requestBody) {
        String originalUrl = requestBody.get("originalUrl");

        if (originalUrl == null || originalUrl.trim().isEmpty()) {
            // If the originalUrl is missing or empty, return a bad request status.
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Original URL is required.");
        }

        String shortCode = urlShortenerService.shortenUrl(originalUrl);

        // For a full URL, you might construct it based on the server's base URL.
        // For simplicity, we'll return just the short code here.
        // If you want the full URL, you could do: "http://localhost:8080/" + shortCode
        Map<String, String> response = new HashMap<>();
        response.put("shortCode", shortCode); // Provide the generated short code.
        // If running locally, you could provide the full short URL like this:
        // response.put("shortUrl", "http://localhost:8080/" + shortCode);

        // Return the response with HTTP status 201 (Created).
        return new ResponseEntity<>(response, HttpStatus.CREATED);
    }

    /**
     * API endpoint to redirect from a short code to its original URL.
     * Accessible via GET requests to "/{shortCode}".
     *
     * @param shortCode The short code extracted from the URL path (e.g., "/abcde123").
     * @param response  HttpServletResponse to perform the redirect.
     * @throws IOException If there's an error during redirection.
     *                     Returns HTTP status 404 (Not Found) if the short code does not exist.
     */
    @GetMapping("/{shortCode}")
    public void redirectToOriginalUrl(@PathVariable String shortCode, HttpServletResponse response) throws IOException {
        // Use the service to get the original URL for the given short code.
        String originalUrl = urlShortenerService.getOriginalUrl(shortCode)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Short URL not found."));

        // Redirect the client's browser to the original URL.
        // HttpServletResponse.sendRedirect() is the standard way to do this in servlets.
        response.sendRedirect(originalUrl);
    }
}
