package com.example.testingdemo.service;

import com.example.testingdemo.model.Product;
import org.springframework.stereotype.Service;

import java.math.BigDecimal;
import java.util.HashMap;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.atomic.AtomicLong;

@Service // Marks this class as a Spring Service component
public class ProductService {

    // Simulating a database with an in-memory map for simplicity
    private final Map<Long, Product> products = new HashMap<>();
    private final AtomicLong idCounter = new AtomicLong(); // Used to generate unique IDs

    // Constructor to pre-populate some data
    public ProductService() {
        createProduct(new Product(null, "Laptop", BigDecimal.valueOf(1200.00)));
        createProduct(new Product(null, "Mouse", BigDecimal.valueOf(25.00)));
    }

    /**
     * Retrieves a product by its ID.
     * @param id The ID of the product to retrieve.
     * @return An Optional containing the Product if found, or empty if not.
     */
    public Optional<Product> getProductById(Long id) {
        // Return the product from the map if it exists
        return Optional.ofNullable(products.get(id));
    }

    /**
     * Creates a new product and assigns it a unique ID.
     * @param product The product object to create (ID will be ignored and generated).
     * @return The newly created product with its generated ID.
     */
    public Product createProduct(Product product) {
        // Generate a new unique ID for the product
        Long newId = idCounter.incrementAndGet();
        product.setId(newId);
        // Store the product in our "database"
        products.put(newId, product);
        return product;
    }
}
