class ProductServiceTest {

    // @InjectMocks creates an instance of ProductService and injects mocks into it
    // In this case, ProductService itself doesn't have dependencies, so it just creates the service.
    @InjectMocks
    private ProductService productService;

    // This method runs before each test. We can use it to reset or set up our test environment.
    @BeforeEach
    void setUp() {
        // For a simple in-memory service like this, we might want to reinitialize it for each test
        // to ensure tests are independent. The @InjectMocks will create a new instance, so this is fine.
        // If the service had a true repository dependency, we would mock that here.
    }

    @Test
    @DisplayName("Should create a product successfully and assign an ID")
    void shouldCreateProductSuccessfully() {
        // Given a new product without an ID
        Product newProduct = new Product(null, "Keyboard", BigDecimal.valueOf(75.00));

        // When we call the createProduct method
        Product createdProduct = productService.createProduct(newProduct);

        // Then, the product should have a non-null ID
        assertThat(createdProduct).isNotNull();
        assertThat(createdProduct.getId()).isNotNull();
        // And the other properties should match
        assertThat(createdProduct.getName()).isEqualTo("Keyboard");
        assertThat(createdProduct.getPrice()).isEqualByComparingTo(BigDecimal.valueOf(75.00));
    }

    @Test
    @DisplayName("Should retrieve an existing product by ID")
    void shouldRetrieveExistingProductById() {
        // Given an existing product (created during service initialization or manually created)
        // Let's create one explicitly for testing getProductById after it's created.
        Product productToCreate = new Product(null, "Monitor", BigDecimal.valueOf(300.00));
        Product createdProduct = productService.createProduct(productToCreate);
        Long productId = createdProduct.getId();

        // When we try to retrieve it by its ID
        Optional<Product> foundProduct = productService.getProductById(productId);

        // Then, it should be present and match the created product
        assertThat(foundProduct).isPresent();
        assertThat(foundProduct.get().getId()).isEqualTo(productId);
        assertThat(foundProduct.get().getName()).isEqualTo("Monitor");
    }

    @Test
    @DisplayName("Should return empty Optional for non-existent product ID")
    void shouldReturnEmptyOptionalForNonExistentProduct() {
        // Given an ID that doesn't correspond to any product
        Long nonExistentId = 999L; // Assuming 999 is not used by our service's internal counter

        // When we try to retrieve a product with that ID
        Optional<Product> foundProduct = productService.getProductById(nonExistentId);

        // Then, the Optional should be empty
        assertThat(foundProduct).isEmpty();
    }
}
