    private MockMvc mockMvc;

    // @MockBean adds mock objects to the Spring application context.
    // Here, we mock ProductService so the controller doesn't depend on the real service logic
    // or its (simulated) database.
    @MockBean
    private ProductService productService;

    // ObjectMapper is used to convert Java objects to JSON strings and vice versa.
    @Autowired
    private ObjectMapper objectMapper;

    @Test
    @DisplayName("Should return product when GET /products/{id} is called with existing ID")
    void shouldReturnProductWhenGetProductByIdWithExistingId() throws Exception {
        // Given an existing product
        Long productId = 1L;
        Product product = new Product(productId, "Laptop", BigDecimal.valueOf(1200.00));

        // When productService.getProductById(productId) is called, return the product
        when(productService.getProductById(productId)).thenReturn(Optional.of(product));

        // Then, perform a GET request and assert the response
        mockMvc.perform(get("/products/{id}", productId))
                .andExpect(status().isOk()) // Expect HTTP 200 OK
                .andExpect(content().contentType(MediaType.APPLICATION_JSON)) // Expect JSON content
                .andExpect(jsonPath("$.id").value(productId)) // Expect ID in JSON response
                .andExpect(jsonPath("$.name").value("Laptop")) // Expect name in JSON response
                .andExpect(jsonPath("$.price").value(1200.00)); // Expect price in JSON response
    }

    @Test
    @DisplayName("Should return 404 Not Found when GET /products/{id} is called with non-existent ID")
    void shouldReturnNotFoundWhenGetProductByIdWithNonExistentId() throws Exception {
        // Given a non-existent product ID
        Long nonExistentId = 999L;

        // When productService.getProductById(nonExistentId) is called, return an empty Optional
        when(productService.getProductById(nonExistentId)).thenReturn(Optional.empty());

        // Then, perform a GET request and expect HTTP 404 Not Found
        mockMvc.perform(get("/products/{id}", nonExistentId))
                .andExpect(status().isNotFound()); // Expect HTTP 404 Not Found
    }

    @Test
    @DisplayName("Should create product when POST /products is called with valid product data")
    void shouldCreateProductWhenPostProduct() throws Exception {
        // Given a new product to be created
        Product newProduct = new Product(null, "Mouse", BigDecimal.valueOf(25.00));
        Product createdProduct = new Product(2L, "Mouse", BigDecimal.valueOf(25.00)); // Product after creation with ID

        // When productService.createProduct(any(Product.class)) is called, return the created product
        // `any(Product.class)` means we don't care about the exact product object passed to the service,
        // just that a Product object is passed.
        when(productService.createProduct(any(Product.class))).thenReturn(createdProduct);

        // Then, perform a POST request with the new product in JSON format
        mockMvc.perform(post("/products")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(newProduct))) // Convert Product object to JSON string
                .andExpect(status().isCreated()) // Expect HTTP 201 Created
                .andExpect(content().contentType(MediaType.APPLICATION_JSON))
                .andExpect(jsonPath("$.id").value(2L)) // Expect the ID assigned by the service mock
                .andExpect(jsonPath("$.name").value("Mouse"))
                .andExpect(jsonPath("$.price").value(25.00));
    }
